namespace ghidra.app.util.pcode;

using ghidra.app.plugin.processors.sleigh.template;
using ghidra.program.model.lang;

public class StringPcodeFormatter : AbstractPcodeFormatter<string, StringPcodeFormatter.ToStringAppender> {
	private static readonly string EOL = System.getProperty("line.separator");

	private int maxDisplayLines = 0; // no limit by default
	private bool displayRawPcode = false;

	/* @Override */
	protected ToStringAppender createAppender(Language language, bool indent) {
		return new ToStringAppender(language, indent);
	}

	/* @Override */
	public bool isFormatRaw() {
		return displayRawPcode;
	}

	/* @Override */
	protected FormatResult formatOpTemplate(ToStringAppender appender, OpTpl op) {
		if (maxDisplayLines > 0 && appender.lineCount >= maxDisplayLines) {
			return FormatResult.TERMINATE;
		}
		FormatResult result = base.formatOpTemplate(appender, op);
		appender.appendEndOfLine();
		return result;
	}

	protected static class ToStringAppender : AbstractAppender<string> {
		private StringBuffer buf = new StringBuffer();
		private int lineCount = 0;

		public ToStringAppender(Language language, bool labeled) : base(language, labeled)
    {
		}

		protected void appendEndOfLine() {
			if (buf.length() != 0) {
				buf.append(EOL);
			}
			lineCount++;
		}

		/* @Override */
		protected void appendString(string string) {
			buf.append(string);
		}

		/* @Override */
		public string finish() {
			return buf.toString();
		}
	}
}
